export async function appendSessionRawEvent(
	plugin: FlexibleWorkbenchPlugin,
	internalId: string,
	stream: "meta" | "stdout" | "stderr",
	value: string,
): Promise<void> {
	const folder = plugin.manifest.dir ? `${plugin.manifest.dir}/session-events` : `${plugin.app.vault.configDir}/plugins/${plugin.manifest.id}/session-events`;
	const adapter = plugin.app.vault.adapter as typeof plugin.app.vault.adapter & { getFullPath(path: string): string };
	const fullFolder = adapter.getFullPath(folder);
	const fullPath = `${fullFolder}/${internalId}.jsonl`;
	const fs = nodeRequire()("node:fs") as { promises: { mkdir(path: string, options: { recursive: boolean }): Promise<void>; appendFile(path: string, data: string, encoding: string): Promise<void> } };
	await fs.promises.mkdir(fullFolder, { recursive: true });
	await fs.promises.appendFile(fullPath, `${JSON.stringify({ at: new Date().toISOString(), stream, value })}\n`, "utf8");
}

export function stopKnowledgeProcesses(): void {
	for (const child of activeChildren) child.kill("SIGTERM");
	activeChildren.clear();
}

export function sessionNoteHeader(record: KnowledgeSessionRecord): string {
	return [
		"---",
		"capture_source: ai-session",
		"review_status: unreviewed",
		`session_id: ${yamlString(record.id)}`,
		`provider: ${record.provider}`,
		`project_path: ${yamlString(record.projectPath)}`,
		`started_at: ${yamlString(record.createdAt)}`,
		"---",
		"",
		`# ${record.title}`,
		"",
		`Project directory: \`${record.projectPath}\``,
		"",
	].join("\n");
}

export async function saveSessionIndex(plugin: FlexibleWorkbenchPlugin): Promise<void> {
	// Session metadata changes while the CLI streams. A view-wide settings
	// refresh here would detach the visible transcript before the process ends.
	await plugin.saveData(plugin.settings);
}

export function sessionRecords(plugin: FlexibleWorkbenchPlugin): KnowledgeSessionRecord[] {
	return plugin.settings.knowledgeSessions ?? (plugin.settings.knowledgeSessions = []);
}

export function reportKnowledgeError(error: unknown): void {
	const message = error instanceof Error ? error.message : String(error);
	new Notice(`Knowledge Workbench: ${message}`);
}

