import { Notice, TFile, TFolder, type App } from "obsidian";
import type FlexibleWorkbenchPlugin from "./main";
import type {
	KnowledgeConfig,
	KnowledgeProvider,
	KnowledgeSessionRecord,
} from "./types";

export type KnowledgeSourceKind = "inbox" | "answer" | "session" | "favorite" | "wiki";

export interface KnowledgeSource {
	path: string;
	title: string;
	content: string;
	kind: KnowledgeSourceKind;
	reviewed: boolean;
	score?: number;
}

export interface CliStreamUpdate {
	text: string;
	replace?: boolean;
	sessionId?: string;
	activity?: string;
}

export interface CliRunOptions {
	provider: KnowledgeProvider;
	prompt: string;
	cwd: string;
	resumeId?: string;
	mode?: "agent" | "read-only";
	onUpdate?: (update: CliStreamUpdate) => void;
	onRaw?: (stream: "stdout" | "stderr", line: string) => void;
}

export interface CliRunHandle {
	done: Promise<{ text: string; sessionId?: string; cancelled: boolean }>;
	cancel(): void;
}

interface NodeChild extends EventEmitterLike {
	stdout?: StreamLike;
	stderr?: StreamLike;
	kill(signal?: string): boolean;
}

interface EventEmitterLike {
	on(event: string, callback: (...args: unknown[]) => void): this;
}

interface StreamLike extends EventEmitterLike {
	setEncoding(encoding: string): this;
}

type NodeRequire = (id: string) => unknown;
const activeChildren = new Set<NodeChild>();

function nodeRequire(): NodeRequire {
	const loadNode = (window as Window & { require?: NodeRequire }).require;
	if (!loadNode) throw new Error("Node.js APIs are unavailable in this Obsidian window.");
	return loadNode;
}

function cliEnvironment(): Record<string, string | undefined> {
	const loadNode = nodeRequire();
	const nodeProcess = loadNode("node:process") as { env: Record<string, string | undefined>; platform: string };
	const path = loadNode("node:path") as { delimiter: string; join(...parts: string[]): string };
	const fs = loadNode("node:fs") as { existsSync(path: string): boolean; readdirSync(path: string): string[] };
	const home = nodeProcess.env.HOME ?? nodeProcess.env.USERPROFILE ?? "";
	const paths = [
		home && path.join(home, ".npm-global", "bin"),
		home && path.join(home, ".local", "bin"),
		home && path.join(home, ".volta", "bin"),
		home && path.join(home, ".bun", "bin"),
		nodeProcess.platform === "darwin" ? "/opt/homebrew/bin" : "",
		"/usr/local/bin",
	];
	if (home) {
		const nvm = path.join(home, ".nvm", "versions", "node");
		try {
			for (const version of fs.readdirSync(nvm)) paths.push(path.join(nvm, version, "bin"));
		} catch {
			// nvm is optional; the inherited PATH still covers other installs.
		}
	}
	const uniquePaths = [...new Set(paths.filter((item) => item && fs.existsSync(item)))];
	return { ...nodeProcess.env, PATH: [...uniquePaths, nodeProcess.env.PATH ?? ""].filter(Boolean).join(path.delimiter) };
}

export function defaultKnowledgeConfig(app: App): KnowledgeConfig {
	return {
		inboxFolder: "Inbox",
		wikiFolder: "Wiki",
		sessionNotesFolder: "AI Sessions",
		projectPath: fullVaultPath(app, ""),
		provider: "codex",
	};
}

export function ensureKnowledgeConfig(app: App, config: KnowledgeConfig | undefined): KnowledgeConfig {
	const defaults = defaultKnowledgeConfig(app);
	const value = (config ??= { ...defaults });
	value.inboxFolder = cleanVaultFolder(value.inboxFolder) || defaults.inboxFolder;
	value.wikiFolder = cleanVaultFolder(value.wikiFolder) || defaults.wikiFolder;
	value.sessionNotesFolder = cleanVaultFolder(value.sessionNotesFolder) || defaults.sessionNotesFolder;
	value.projectPath = value.projectPath?.trim() || defaults.projectPath;
	value.provider = value.provider === "claude" ? "claude" : "codex";
	return value;
}

export function cleanVaultFolder(folder: string | undefined): string {
	return (folder ?? "")
		.trim()
		.replace(/\\/g, "/")
		.replace(/^\/+|\/+$/g, "")
		.split("/")
		.filter((part) => part && part !== "." && part !== "..")
		.join("/");
}

export function isAbsoluteProjectPath(value: string): boolean {
	const path = value.trim();
	return path.startsWith("/") || path.startsWith("\\\\") || /^[A-Za-z]:[\\/]/.test(path);
}

export function fullVaultPath(app: App, path: string): string {
	const adapter = app.vault.adapter as typeof app.vault.adapter & { getFullPath(normalizedPath: string): string };
	return adapter.getFullPath(path);
}

export async function ensureKnowledgeFolder(app: App, path: string): Promise<void> {
	let built = "";
	for (const part of cleanVaultFolder(path).split("/").filter(Boolean)) {
		built = built ? `${built}/${part}` : part;
		const found = app.vault.getAbstractFileByPath(built);
		if (found instanceof TFolder) continue;
		if (found) throw new Error(`A file already uses this folder path: ${built}`);
		await app.vault.createFolder(built);
	}
}

function yamlString(value: string): string {
	return JSON.stringify(value);
}

function filenamePart(value: string): string {
	return value
		.replace(/[\\/:*?"<>|#^[\]`]/g, " ")
		.replace(/[\s.]+/g, " ")
	.trim()
	.slice(0, 64);
}

function uniqueName(app: App, folder: string, base: string): string {
	let candidate = `${folder}/${base}.md`;
	for (let n = 2; app.vault.getAbstractFileByPath(candidate); n++) {
		candidate = `${folder}/${base} ${n}.md`;
	}
	return candidate;
}

export async function createCapture(
	app: App,
	config: KnowledgeConfig,
	text: string,
	source: "inbox" | "answer",
): Promise<TFile> {
	const content = text.trim();
	if (!content) throw new Error("Write something before saving it.");
	const folder = cleanVaultFolder(config.inboxFolder);
	await ensureKnowledgeFolder(app, folder);
	const now = new Date();
	const time = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")} ${String(now.getHours()).padStart(2, "0")}-${String(now.getMinutes()).padStart(2, "0")}-${String(now.getSeconds()).padStart(2, "0")}`;
	const title = filenamePart(content.split(/\r?\n/)[0].replace(/^https?:\/\//, "")) || "Quick capture";
	const path = uniqueName(app, folder, `${time} ${title}`);
	const note = [
		"---",
		`captured_at: ${yamlString(now.toISOString())}`,
		`capture_source: ${source}`,
		"review_status: unreviewed",
		"---",
		"",
		content,
		"",
	].join("\n");
	return app.vault.create(path, note);
}

export async function readKnowledgeSource(app: App, path: string, kind: KnowledgeSourceKind): Promise<KnowledgeSource | null> {
	const file = app.vault.getAbstractFileByPath(path);
	if (!(file instanceof TFile) || file.extension !== "md") return null;
	const cache = app.metadataCache.getFileCache(file);
	return {
		path: file.path,
		title: file.basename,
		content: await app.vault.cachedRead(file),
		kind,
		reviewed: cache?.frontmatter?.review_status === "reviewed",
	};
}

export async function collectInbox(app: App, config: KnowledgeConfig): Promise<KnowledgeSource[]> {
	const folder = cleanVaultFolder(config.inboxFolder);
	const files = app.vault.getMarkdownFiles().filter((file) => {
		const cache = app.metadataCache.getFileCache(file);
		const inFolder = file.path.startsWith(`${folder}/`);
		return inFolder && cache?.frontmatter?.review_status !== "reviewed";
	});
	const sources = await Promise.all(files.map((file) => readKnowledgeSource(app, file.path, "inbox")));
	return sources.filter((source): source is KnowledgeSource => source !== null)
		.sort((a, b) => b.path.localeCompare(a.path));
}

