export function buildCliArgs(options: CliRunOptions): string[] {
	const readonly = options.mode === "read-only";
	if (options.provider === "codex") {
		const args = ["exec"];
		if (options.resumeId) args.push("resume");
		args.push("--json");
		if (!options.resumeId) args.push("-C", options.cwd);
		args.push("--skip-git-repo-check");
		if (readonly) args.push("--sandbox", "read-only");
		else args.push("--dangerously-bypass-approvals-and-sandbox");
		if (options.resumeId) args.push(options.resumeId);
		args.push(options.prompt);
		return args;
	}
	const args = ["-p", "--output-format", "stream-json", "--include-partial-messages", "--verbose"];
	if (options.resumeId) args.push("--resume", options.resumeId);
	if (readonly) args.push("--permission-mode", "plan");
	else args.push("--permission-mode", "bypassPermissions", "--dangerously-skip-permissions");
	args.push(options.prompt);
	// `--tools` takes a variable number of values; keep it after the prompt so
	// Claude Code doesn't parse the prompt itself as a tool name.
	if (readonly) args.push("--tools", "");
	return args;
}

