/** Parse the stable text and session-id fields emitted by both supported JSONL CLIs. */
export function parseCliStreamLine(provider: KnowledgeProvider, line: string): CliStreamUpdate | null {
	let event: Record<string, unknown>;
	try {
		const value: unknown = JSON.parse(line);
		if (!value || typeof value !== "object") return null;
		event = value as Record<string, unknown>;
	} catch {
		return null;
	}
	const sessionId = typeof event.session_id === "string"
		? event.session_id
		: typeof event.thread_id === "string" ? event.thread_id : undefined;
	if (provider === "claude") {
		const streamEvent = event.event as Record<string, unknown> | undefined;
		const delta = streamEvent?.delta as Record<string, unknown> | undefined;
		if (typeof delta?.text === "string") return { text: delta.text, sessionId };
		const block = streamEvent?.content_block as Record<string, unknown> | undefined;
		if (streamEvent?.type === "content_block_start" && block?.type === "tool_use" && typeof block.name === "string") {
			return { text: "", activity: toolActivity(block.name), sessionId };
		}
		if (event.type === "assistant") {
			const message = event.message as Record<string, unknown> | undefined;
			const text = parseTextContent(message?.content);
			const activities = claudeToolActivities(message?.content);
			if (text || activities.length) return { text, replace: true, activity: activities.join(" · ") || undefined, sessionId };
		}
		if (event.type === "result" && typeof event.result === "string") {
			return { text: event.result, replace: true, sessionId };
		}
	} else {
		const type = typeof event.type === "string" ? event.type : "";
		const thread = event.thread as Record<string, unknown> | undefined;
		const id = sessionId ?? (typeof thread?.id === "string" ? thread.id : undefined);
		const delta = event.delta as Record<string, unknown> | undefined;
		if (type === "item.delta" && delta) {
			const text = typeof delta.text === "string" ? delta.text : typeof delta.content === "string" ? delta.content : "";
			if (text) return { text, sessionId: id };
		}
		const item = event.item as Record<string, unknown> | undefined;
		if (type === "item.started" && item && typeof item.type === "string") {
			const detail = typeof item.command === "string" ? item.command :
				typeof item.path === "string" ? item.path :
				typeof item.name === "string" ? item.name : undefined;
			const labels: Record<string, string> = {
				command_execution: "Run command",
				file_change: "Change files",
				mcp_tool_call: "Call integration",
				web_search_call: "Search web",
			};
			const label = labels[item.type];
			if (label) return { text: "", activity: toolActivity(label, detail), sessionId: id };
		}
		if (type === "item.completed" && item?.type === "agent_message" && typeof item.text === "string") {
			return { text: item.text, replace: true, sessionId: id };
		}
		const message = event.message as Record<string, unknown> | undefined;
		if (typeof message?.text === "string" && /message|completed/.test(type)) {
			return { text: message.text, replace: true, sessionId: id };
		}
		if (sessionId) return { text: "", sessionId };
	}
	return sessionId ? { text: "", sessionId } : null;
}

