import { buildCliArgs, cleanVaultFolder, isAbsoluteProjectPath, parseCliStreamLine, scoreKnowledgeText } from "../src/knowledge";

describe("Knowledge Workbench helpers", () => {
	it("normalizes vault folders without allowing parent traversal", () => {
		expect(cleanVaultFolder(" /Notes\\Inbox/../Capture/ ")).toBe("Notes/Inbox/Capture");
	});

	it("accepts absolute project directories on macOS and Windows", () => {
		expect(isAbsoluteProjectPath("/Users/alex/project")).toBe(true);
		expect(isAbsoluteProjectPath("C:\\work\\project")).toBe(true);
		expect(isAbsoluteProjectPath("relative/project")).toBe(false);
	});

	it("ranks exact topic matches ahead of partial Chinese token matches", () => {
		const exact = scoreKnowledgeText("关于每周整理的完整说明", "每周整理");
		const partial = scoreKnowledgeText("每周要做的事情", "每周整理");
		expect(exact).toBeGreaterThan(partial);
	});

	it("reads Codex thread ids, streamed text deltas and completed messages", () => {
		expect(parseCliStreamLine("codex", '{"type":"thread.started","thread_id":"thread-1"}'))
			.toEqual({ text: "", sessionId: "thread-1" });
		expect(parseCliStreamLine("codex", '{"type":"item.delta","delta":{"type":"text_delta","text":"hello"}}'))
			.toEqual({ text: "hello", sessionId: undefined });
		expect(parseCliStreamLine("codex", '{"type":"item.completed","item":{"type":"agent_message","text":"done"}}'))
			.toEqual({ text: "done", replace: true, sessionId: undefined });
	});

	it("reads Claude Code streaming and final response events", () => {
		expect(parseCliStreamLine("claude", '{"type":"stream_event","session_id":"claude-1","event":{"type":"content_block_delta","delta":{"type":"text_delta","text":"hello"}}}'))
			.toEqual({ text: "hello", sessionId: "claude-1" });
		expect(parseCliStreamLine("claude", '{"type":"result","session_id":"claude-1","result":"finished"}'))
			.toEqual({ text: "finished", replace: true, sessionId: "claude-1" });
	});

	it("exposes tool operations as activity updates", () => {
		expect(parseCliStreamLine("codex", '{"type":"item.started","item":{"type":"command_execution","command":"npm run build"}}'))
			.toMatchObject({ activity: "Run command: npm run build" });
		expect(parseCliStreamLine("claude", '{"type":"stream_event","event":{"type":"content_block_start","content_block":{"type":"tool_use","name":"Edit"}}}'))
			.toMatchObject({ activity: "Edit" });
	});

	it("starts Codex sessions in the visible project directory with automatic approval", () => {
		const args = buildCliArgs({ provider: "codex", cwd: "/work/project", prompt: "change this" });
		expect(args).toContain("--dangerously-bypass-approvals-and-sandbox");
		expect(args.slice(args.indexOf("-C"), args.indexOf("-C") + 2)).toEqual(["-C", "/work/project"]);
	});

	it("resumes Codex by its persisted id without passing an unsupported cwd option", () => {
		const args = buildCliArgs({ provider: "codex", cwd: "/work/project", resumeId: "thread-1", prompt: "continue" });
		expect(args).toContain("resume");
		expect(args).toContain("thread-1");
		expect(args).not.toContain("-C");
	});

	it("starts Claude Code with bypass permissions and can resume its saved id", () => {
		const args = buildCliArgs({ provider: "claude", cwd: "/work/project", resumeId: "claude-1", prompt: "continue" });
		expect(args).toContain("--dangerously-skip-permissions");
		expect(args.slice(args.indexOf("--resume"), args.indexOf("--resume") + 2)).toEqual(["--resume", "claude-1"]);
	});

	it("keeps Wiki and Q&A invocations read-only with Claude's tools option after the prompt", () => {
		const claude = buildCliArgs({ provider: "claude", cwd: "/work/project", prompt: "draft this", mode: "read-only" });
		expect(claude).toContain("--permission-mode");
		expect(claude).toContain("plan");
		expect(claude.slice(-2)).toEqual(["--tools", ""]);
		expect(claude.indexOf("draft this")).toBeLessThan(claude.indexOf("--tools"));
		const codex = buildCliArgs({ provider: "codex", cwd: "/work/project", prompt: "answer this", mode: "read-only" });
		expect(codex.slice(codex.indexOf("--sandbox"), codex.indexOf("--sandbox") + 2)).toEqual(["--sandbox", "read-only"]);
		expect(codex).not.toContain("--dangerously-bypass-approvals-and-sandbox");
	});
});
