export async function retrieveKnowledge(
	app: App,
	config: KnowledgeConfig,
	query: string,
	additionalRawPaths: string[] = [],
): Promise<KnowledgeSource[]> {
	const wikiFolder = cleanVaultFolder(config.wikiFolder);
	const wikiFiles = app.vault.getMarkdownFiles().filter((file) =>
		file.path.startsWith(`${wikiFolder}/`) &&
		app.metadataCache.getFileCache(file)?.frontmatter?.review_status === "reviewed",
	);
	const reviewed = await Promise.all(wikiFiles.map((file) => readKnowledgeSource(app, file.path, "wiki")));
	const rankedReviewed = reviewed
		.filter((source): source is KnowledgeSource => source !== null)
		.map((source) => ({ ...source, score: scoreKnowledgeText(`${source.title}\n${source.content}`, query) }))
		.filter((source) => (source.score ?? 0) > 0)
		.sort((a, b) => (b.score ?? 0) - (a.score ?? 0))
		.slice(0, 5);
	if (rankedReviewed.length >= 3) return rankedReviewed;
	const inbox = await collectInbox(app, config);
	const extraPaths = new Set(additionalRawPaths);
	const sessionFolder = cleanVaultFolder(config.sessionNotesFolder);
	for (const file of app.vault.getMarkdownFiles()) {
		if (file.path.startsWith(`${sessionFolder}/`)) extraPaths.add(file.path);
	}
	const extraRaw = await Promise.all([...extraPaths].map((path) => {
		const kind: KnowledgeSourceKind = path.startsWith(`${sessionFolder}/`) ? "session" : "favorite";
		return readKnowledgeSource(app, path, kind);
	}));
	const rawByPath = new Map<string, KnowledgeSource>();
	for (const source of [...inbox, ...extraRaw.filter((item): item is KnowledgeSource => item !== null)]) {
		if (!rawByPath.has(source.path)) rawByPath.set(source.path, source);
	}
	const rankedInbox = [...rawByPath.values()]
		.map((source) => ({ ...source, score: scoreKnowledgeText(`${source.title}\n${source.content}`, query) }))
		.filter((source) => (source.score ?? 0) > 0)
		.sort((a, b) => (b.score ?? 0) - (a.score ?? 0))
		.slice(0, 3);
	return [...rankedReviewed, ...rankedInbox].slice(0, 6);
}

function parseTextContent(value: unknown): string {
	if (typeof value === "string") return value;
	if (Array.isArray(value)) {
		return value.map((item) => {
			if (typeof item === "string") return item;
			if (item && typeof item === "object" && !Array.isArray(item)) {
				const text = (item as Record<string, unknown>).text;
				if (typeof text === "string") return text;
			}
			return "";
		}).join("");
	}
	return "";
}

function toolActivity(name: string, detail?: string): string {
	const summary = detail?.replace(/\s+/g, " ").trim();
	return summary ? `${name}: ${summary.slice(0, 180)}` : name;
}

function claudeToolActivities(value: unknown): string[] {
	if (!Array.isArray(value)) return [];
	return value.flatMap((block) => {
		if (!block || typeof block !== "object" || Array.isArray(block)) return [];
		const item = block as Record<string, unknown>;
		if (item.type !== "tool_use" || typeof item.name !== "string") return [];
		const input = item.input && typeof item.input === "object" ? item.input as Record<string, unknown> : {};
		const detail = typeof input.command === "string" ? input.command :
			typeof input.file_path === "string" ? input.file_path :
			typeof input.pattern === "string" ? input.pattern : undefined;
		return [toolActivity(item.name, detail)];
	});
}

